S = "Hakeem Force Academy"
QS = [
(S, "Who is the Federal Minister for Finance and Revenue of Pakistan?", ["Ishaq Dar", "Muhammad Aurangzeb", "Miftah Ismail", "Shaukat Tarin"], 1, "Muhammad Aurangzeb took charge as Finance Minister in March 2024 and presented the FY2026-27 budget. He is still in office in October 2026.", "In 2022 the finance minister was Miftah Ismail, followed by Ishaq Dar.", [5150]),
(S, "How many seats are reserved for minorities in the National Assembly of Pakistan under the 1973 Constitution?", ["5", "10", "15", "20"], 1, "The 1973 Constitution reserves 10 seats for non-Muslim minorities in the National Assembly. This number is unchanged in the current 336-seat House.", "The National Assembly has 266 general seats, 60 women seats and 10 minority seats.", [853]),
(S, "In which year did the Minto-Morley Reforms (Indian Councils Act) come into effect?", ["1905", "1909", "1919", "1935"], 1, "The Indian Councils Act of 1909, known as the Minto-Morley Reforms, introduced separate electorates for Muslims. Lord Minto was Viceroy and Lord Morley was Secretary of State for India.", "The Montagu-Chelmsford Reforms followed in 1919.", [2715, 8]),
(S, "A train covers 20 km in one hour. About how much distance does it cover in 1 minute?", ["0.2 km", "0.33 km", "0.5 km", "1.2 km"], 1, "1 hour is 60 minutes, so distance per minute is 20 divided by 60, which is 0.33 km. This is about 333 metres.", "Speed in km/h divided by 60 gives km per minute.", [1653]),
(S, "If 1 man writes 5 papers in 5 minutes, how many papers does he write in one minute?", ["1", "5", "25", "0.5"], 0, "Rate is 5 papers divided by 5 minutes, which is 1 paper per minute.", "Rate equals work divided by time.", [2318]),
(S, "If 5 men write 5 pages in 1 minute, how much time will 1 man take to write 1 page?", ["5 minutes", "1 minute", "25 minutes", "30 seconds"], 1, "5 men write 5 pages in 1 minute, so each man writes 1 page in 1 minute. One man therefore needs 1 minute for 1 page.", "If each worker works at the same rate, work per worker is total work divided by number of workers.", [2327]),
(S, "What was the real name of the Bengali freedom fighter Tito Mir?", ["Syed Mir Nisar Ali", "Mir Jafar Ali", "Nisar Ahmad Khan", "Syed Ahmad Shaheed"], 0, "Tito Mir's real name was Syed Mir Nisar Ali. He led a peasant uprising against landlords and the British in Bengal in 1831.", "He built a bamboo fort at Narkelberia and died fighting in 1831.", [4160]),
(S, "On which date of the Islamic calendar is Shab-e-Miraj (the Night Journey of the Holy Prophet PBUH) commemorated?", ["27 Rajab", "12 Rabi-ul-Awwal", "15 Shaban", "27 Ramadan"], 0, "The Night Journey and Ascension (Isra and Miraj) is traditionally observed on 27 Rajab. It took place about the 10th to 11th year of prophethood.", "Scholars differ on the exact date, but 27 Rajab is the commonly accepted one in Pakistan.", [2883]),
(S, "If a helicopter needs 80 gallons of fuel to move 320 km, how many gallons are needed to cover 400 km?", ["90", "100", "110", "120"], 1, "Fuel per km is 80 divided by 320 = 0.25 gallons. For 400 km, 400 x 0.25 = 100 gallons.", "Fuel used is directly proportional to distance.", [2349]),
(S, "If a helicopter needs 50 gallons of fuel to move 320 km, how many gallons are needed to cover 400 km?", ["60", "62.5", "65", "70"], 1, "Fuel per km is 50 divided by 320. For 400 km, 400 x 50 / 320 = 62.5 gallons.", "This is a direct proportion question.", [522]),
(S, "In a class of 1500 students, 1300 are present. What percentage of students are absent?", ["10.5%", "12%", "13.33%", "15%"], 2, "Absent students = 1500 - 1300 = 200. Percentage = 200 / 1500 x 100 = 13.33%.", "Present percentage is 86.67%, and the two add up to 100%.", [898]),
(S, "Which planet has the largest number of moons?", ["Jupiter", "Saturn", "Uranus", "Neptune"], 1, "Saturn has the most confirmed moons of any planet, about 293 as of 2026. Jupiter is second with about 115.", "Saturn's count was 83 in 2022 and rose sharply after new discoveries, so older answers differ.", [181, 232, 4831, 4832]),
(S, "Which planet has the largest moon in the Solar System?", ["Saturn", "Jupiter", "Mars", "Neptune"], 1, "Ganymede, a moon of Jupiter, is the largest moon in the Solar System. It is even bigger than the planet Mercury.", "Saturn's largest moon, Titan, is second in size.", [1355]),
(S, "Who was the first man to land on the Moon?", ["Buzz Aldrin", "Neil Armstrong", "Yuri Gagarin", "Michael Collins"], 1, "Neil Armstrong of the Apollo 11 mission stepped on the Moon on 20 July 1969.", "Buzz Aldrin followed him, while Michael Collins stayed in orbit.", [5344, 5359]),
(S, "Which pronoun is most suitable for the word mom?", ["He", "She", "It", "They"], 1, "Mom is a female parent, so the feminine subject pronoun she is used.", "Her is the object form and herself is the reflexive form.", [3800, 4841]),
(S, "If the 2nd day of a month is Monday, what day will the 9th be?", ["Sunday", "Monday", "Tuesday", "Wednesday"], 1, "The 9th is 7 days after the 2nd. After a full week the day repeats, so it is Monday.", "Any two dates 7 days apart fall on the same weekday.", [2405]),
(S, "Whose motto is Faith, Unity, Discipline?", ["Allama Iqbal", "Quaid-e-Azam Muhammad Ali Jinnah", "Liaquat Ali Khan", "Sir Syed Ahmad Khan"], 1, "Quaid-e-Azam Muhammad Ali Jinnah gave the motto Faith, Unity, Discipline (Iman, Ittehad, Tanzeem) to the nation.", "It is the national motto of Pakistan.", [160]),
(S, "What is the motto given by the Quaid-e-Azam to the nation?", ["Unity, Faith, Discipline", "Faith, Unity, Discipline", "Freedom, Peace, Progress", "Work, Duty, Honour"], 1, "The Quaid's motto is Faith, Unity, Discipline. It appears as Iman, Ittehad, Tanzeem in Urdu.", "Some people write it as Unity, Faith, Discipline, but the official order is Faith, Unity, Discipline.", [3724, 3802]),
(S, "Which is the highest mountain in the world above sea level?", ["K2", "Mount Everest", "Kangchenjunga", "Nanga Parbat"], 1, "Mount Everest is about 8,849 m high, the highest peak above sea level.", "K2 on the Pakistan-China border is the second highest.", [4041]),
(S, "In which year did Lord Mountbatten arrive in India as the last Viceroy?", ["1945", "1946", "1947", "1948"], 2, "Lord Mountbatten arrived in India in March 1947 to oversee the transfer of power. He announced the Partition plan on 3 June 1947.", "He later became the first Governor General of independent India.", [2691]),
(S, "A train moves at 120 km/h. What distance does it cover in 120 minutes?", ["120 km", "180 km", "240 km", "360 km"], 2, "120 minutes is 2 hours. Distance = 120 x 2 = 240 km.", "Convert minutes to hours by dividing by 60.", [1659]),
(S, "A train is moving at a speed of 60 km/h. How much distance does it cover in 10 minutes?", ["6 km", "10 km", "12 km", "15 km"], 1, "10 minutes is 1/6 hour. Distance = 60 x 1/6 = 10 km.", "At 60 km/h a train covers 1 km each minute.", [1656]),
(S, "In which year was Islamabad officially made the capital of Pakistan, replacing Rawalpindi as interim capital?", ["1960", "1963", "1967", "1971"], 2, "Karachi was first capital, then Rawalpindi served as interim capital while Islamabad was built. Islamabad officially became the capital in 1967.", "Sources differ on the exact year, since the decision was taken in 1959-60 and the shift happened in stages.", [4280]),
(S, "Who moved the Objective Resolution in the Constituent Assembly of Pakistan in 1949?", ["Quaid-e-Azam", "Liaquat Ali Khan", "Khawaja Nazimuddin", "Chaudhry Muhammad Ali"], 1, "Prime Minister Liaquat Ali Khan moved the Objective Resolution, and it was passed on 12 March 1949.", "It later became the preamble of the 1973 Constitution.", [5232]),
(S, "Hazrat Muaz bin Jabal (RA) was appointed governor of which place by the Holy Prophet (PBUH)?", ["Yemen", "Syria", "Egypt", "Bahrain"], 0, "The Holy Prophet (PBUH) sent Hazrat Muaz bin Jabal (RA) to Yemen as governor and teacher.", "He was known as the most knowledgeable Companion about halal and haram.", [830, 1529, 265]),
(S, "How many companions are called the Ashra Mubashra?", ["7", "10", "12", "14"], 1, "Ashra Mubashra are ten Companions who were given the glad tidings of Paradise in their lifetime.", "They include the four Rightly Guided Caliphs.", [995]),
(S, "Which of the following is one of the Ashra Mubashra?", ["Hazrat Talha bin Ubaidullah (RA)", "Hazrat Bilal (RA)", "Hazrat Zaid bin Haritha (RA)", "Hazrat Khalid bin Walid (RA)"], 0, "Hazrat Talha bin Ubaidullah (RA) is among the ten Companions given the glad tidings of Paradise. The others listed are not in the group.", "The ten include Abu Bakr, Umar, Usman, Ali, Zubair, Talha, Abdur Rahman bin Auf, Saad bin Abi Waqqas, Saeed bin Zaid and Abu Ubaidah.", [3166]),
(S, "In which city is Mughalpura (famous for its railway workshops) located?", ["Karachi", "Lahore", "Multan", "Rawalpindi"], 1, "Mughalpura is an area of Lahore and is known for its large railway workshops and station.", "Lahore Junction is the main railway station of the city.", [913, 4352, 1263, 1269]),
(S, "Which city is commonly called the heart of Pakistan?", ["Multan", "Lahore", "Peshawar", "Islamabad"], 1, "Lahore is commonly known as the heart of Pakistan because of its culture and history.", "It is also called the Cultural Capital of Pakistan.", [411]),
(S, "What is the multiplicative inverse of 0.001?", ["100", "1000", "0.1", "10"], 1, "The inverse of a number is 1 divided by it. 1 / 0.001 = 1000.", "A number times its multiplicative inverse equals 1.", [1145]),
(S, "What is the multiplicative inverse of 0.01?", ["10", "1000", "100", "0.1"], 2, "1 / 0.01 = 100.", "Zero has no multiplicative inverse.", [199]),
(S, "What is the relation between multiplication and division?", ["They are inverse operations", "They are the same operation", "They are unrelated", "They are both commutative"], 0, "Division undoes multiplication, so they are inverse operations. For example, 6 x 4 = 24 and 24 / 4 = 6.", "Addition and subtraction are also inverse operations.", [3917]),
(S, "Where is Baitul Muqaddas (Al-Aqsa Mosque) located?", ["Makkah", "Jerusalem", "Madinah", "Damascus"], 1, "Baitul Muqaddas is in Jerusalem, in Palestine. It was the first Qibla of the Muslims.", "The Qibla was changed to the Kaaba in the 2nd year of Hijra.", [4333]),
(S, "What is the title of Hazrat Musa (AS)?", ["Khalilullah", "Kalimullah", "Safiullah", "Ruhullah"], 1, "Hazrat Musa (AS) is called Kalimullah because Allah spoke to him directly.", "Khalilullah is Ibrahim, Safiullah is Adam and Ruhullah is Isa.", [4003]),
(S, "Who was the mother of the Holy Prophet Muhammad (PBUH)?", ["Hazrat Halima", "Hazrat Amina", "Hazrat Khadija", "Hazrat Fatima"], 1, "The Holy Prophet's mother was Hazrat Amina bint Wahb. Halima Sadia was his wet nurse.", "Hazrat Amina passed away when he was about 6 years old.", [5164]),
]
